function parseCSV(text) {
  if (!text) return [];

  // Split into records by newlines, handling \r\n
  const records = text.split(/\r?\n/);

  return records.map(record => {
    const fields = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < record.length; i++) {
      const char = record[i];

      if (inQuotes) {
        if (char === '"') {
          // Check for escaped quote ""
          if (i + 1 < record.length && record[i + 1] === '"') {
            currentField += '"';
            i++; // skip the next quote
          } else {
            // End of quoted field
            inQuotes = false;
          }
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          fields.push(currentField);
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }

    // After processing the record, if we're still in quotes, it's an unclosed quote
    if (inQuotes) {
      throw new SyntaxError('Unclosed quoted field');
    }

    fields.push(currentField);
    return fields;
  });
}
```

